  ('imperfecto', null, 'marker_choice', '{"text": "Hizo amistad con el explorador que se ___ (llamar) Tomás.", "marker": "sustantivo + que", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "llamaba"}', 'imperfecto', 'Zoek de tijdsaanduiding: ''sustantivo + que''.', 'Zelfstandig naamwoord + que beschrijft dat naamwoord → imperfecto. De vorm is: llamaba.', 2, 5, 'marker-detective #5'),
  ('indefinido', null, 'marker_choice', '{"text": "Ayer ___ (hacer, yo) muchos deberes de casa.", "marker": "ayer", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "hice"}', 'indefinido', 'Zoek de tijdsaanduiding: ''ayer''.', '''Ayer'' (gisteren) is een afgesloten moment → indefinido. De vorm is: hice.', 2, 6, 'marker-detective #6'),
  ('indefinido', null, 'marker_choice', '{"text": "Primero ___ (lavar, yo) los platos, luego pasé la aspiradora.", "marker": "primero", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "lavé"}', 'indefinido', 'Zoek de tijdsaanduiding: ''primero''.', 'Opeenvolgende acties (primero, luego...) → indefinido. De vorm is: lavé.', 2, 7, 'marker-detective #7'),
  ('imperfecto', null, 'marker_choice', '{"text": "Antes ___ (jugar, yo) al fútbol todos los sábados.", "marker": "antes", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "jugaba"}', 'imperfecto', 'Zoek de tijdsaanduiding: ''antes''.', '''Antes'' (vroeger) + gewoonte → imperfecto. De vorm is: jugaba.', 2, 8, 'marker-detective #8'),
  ('imperfecto', null, 'marker_choice', '{"text": "De niños, siempre ___ (estar, nosotros) jugando en la calle.", "marker": "siempre", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "estábamos"}', 'imperfecto', 'Zoek de tijdsaanduiding: ''siempre''.', '''Siempre'' (altijd) wijst op een gewoonte → imperfecto. De vorm is: estábamos.', 2, 9, 'marker-detective #9'),
  ('preterito_compuesto', null, 'marker_choice', '{"text": "¿___ (ir, tú) alguna vez a Francia?", "marker": "alguna vez", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "has ido"}', 'preterito_compuesto', 'Zoek de tijdsaanduiding: ''alguna vez''.', '''Alguna vez'' (ooit) tot nu toe → pretérito compuesto. De vorm is: has ido.', 2, 10, 'marker-detective #10'),
  ('preterito_compuesto', null, 'marker_choice', '{"text": "Este año ___ (alquilar, yo) un apartamento en la playa.", "marker": "este año", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "he alquilado"}', 'preterito_compuesto', 'Zoek de tijdsaanduiding: ''este año''.', '''Este año'' begint met este: verbonden met nu → pretérito compuesto. De vorm is: he alquilado.', 2, 11, 'marker-detective #11'),
  ('indefinido', null, 'marker_choice', '{"text": "El lunes pasado ___ (poner, yo) un anuncio para buscar piso.", "marker": "el lunes pasado", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "puse"}', 'indefinido', 'Zoek de tijdsaanduiding: ''el lunes pasado''.', '''El lunes pasado'' is een afgesloten moment → indefinido. De vorm is: puse.', 2, 12, 'marker-detective #12'),
  ('preterito_compuesto', null, 'marker_choice', '{"text": "Hoy ___ (recoger, yo) las llaves de la casa para las vacaciones.", "marker": "hoy", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "he recogido"}', 'preterito_compuesto', 'Zoek de tijdsaanduiding: ''hoy''.', '''Hoy'' (vandaag) → pretérito compuesto. De vorm is: he recogido.', 2, 13, 'marker-detective #13'),
  ('indefinido', null, 'marker_choice', '{"text": "El año pasado ___ (tener, yo) mala suerte con el hotel.", "marker": "el año pasado", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "tuve"}', 'indefinido', 'Zoek de tijdsaanduiding: ''el año pasado''.', '''El año pasado'' is afgesloten → indefinido. De vorm is: tuve.', 2, 14, 'marker-detective #14'),
  ('imperfecto', null, 'marker_choice', '{"text": "Todos los días mi abuela ___ (ir) a la plaza.", "marker": "todos los días", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "iba"}', 'imperfecto', 'Zoek de tijdsaanduiding: ''todos los días''.', '''Todos los días'' (elke dag) is een gewoonte → imperfecto. De vorm is: iba.', 2, 15, 'marker-detective #15'),
  ('indefinido', null, 'marker_choice', '{"text": "Hace tres años ___ (viajar, nosotros) a Perú.", "marker": "hace tres años", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "viajamos"}', 'indefinido', 'Zoek de tijdsaanduiding: ''hace tres años''.', '''Hace x años'' (x jaar geleden) → indefinido. De vorm is: viajamos.', 2, 16, 'marker-detective #16'),
  ('preterito_compuesto', null, 'marker_choice', '{"text": "Todavía no ___ (terminar, yo) los deberes.", "marker": "todavía no", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "he terminado"}', 'preterito_compuesto', 'Zoek de tijdsaanduiding: ''todavía no''.', '''Todavía no'' (nog altijd niet) heeft een band met nu → pretérito compuesto. De vorm is: he terminado.', 2, 17, 'marker-detective #17'),
  ('imperfecto', null, 'marker_choice', '{"text": "No fui a la fiesta porque ___ (estar, yo) muy cansada.", "marker": "porque", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "estaba"}', 'imperfecto', 'Zoek de tijdsaanduiding: ''porque''.', '''Porque'' + imperfecto geeft uitleg over de situatie → imperfecto. De vorm is: estaba.', 2, 18, 'marker-detective #18'),
  ('indefinido', null, 'marker_choice', '{"text": "Anoche ___ (ver, yo) una película en Netflix.", "marker": "anoche", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "vi"}', 'indefinido', 'Zoek de tijdsaanduiding: ''anoche''.', '''Anoche'' (gisteravond) is afgesloten → indefinido. De vorm is: vi.', 2, 19, 'marker-detective #19'),
  ('preterito_compuesto', null, 'marker_choice', '{"text": "Nunca ___ (comer, yo) sushi. ¿Está bueno?", "marker": "nunca", "options": ["preterito_compuesto", "imperfecto", "indefinido"], "form": "he comido"}', 'preterito_compuesto', 'Zoek de tijdsaanduiding: ''nunca''.', '''Nunca'' (nooit) tot nu toe → pretérito compuesto. De vorm is: he comido.', 2, 20, 'marker-detective #20'),
