  ('imperfecto', 'tortuga-elefante', 'multiple_choice', '{"text": "A los dos les **gustaba** hacer las cosas de una manera lenta y sincera.", "question_nl": "In welke tijd staat het vetgedrukte werkwoord?", "options": ["preterito_compuesto", "imperfecto", "indefinido"]}', 'imperfecto', null, 'Beschrijving van hoe ze waren → imperfecto.', 3, 3, 'p27 mezclados EJ8 #3'),
