  ('imperfecto', 'tortuga-elefante', 'multiple_choice', '{"text": "Pensó que no podía seguir porque **estaba** solo.", "question_nl": "In welke tijd staat het vetgedrukte werkwoord?", "options": ["preterito_compuesto", "imperfecto", "indefinido"]}', 'imperfecto', null, '''Porque'' + imperfecto: uitleg over de situatie → imperfecto.', 3, 6, 'p27 mezclados EJ8 #6'),
