  ('indefinido', 'tortuga-elefante', 'multiple_choice', '{"text": "El elefante, cansado pero feliz, **llegó** al pico de la montaña.", "question_nl": "In welke tijd staat het vetgedrukte werkwoord?", "options": ["preterito_compuesto", "imperfecto", "indefinido"]}', 'indefinido', null, 'Afgeronde actie → indefinido.', 3, 8, 'p27 mezclados EJ8 #8'),
